<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { ipcRenderer } from 'electron';
type Attachment={name:string;path:string;size:number}; type Message={id:string;createdAt:string;body:string;attachments:Attachment[]}; type Ticket=Message&{subject:string;replies:Message[]};
type State={logging:{sources:Record<string,boolean>;autoEnabledUntil?:string;lastErrorAt?:string};feedback:Message[];tickets:Ticket[];remote:{status:string;requestedAt?:string;offeredAt?:string;offeredBy?:string;approvedAt?:string;endedAt?:string}};
const sections=['home','logs','feedback','tickets','remote'] as const; const section=ref('home'); const state=ref<State|null>(null); const logs=ref<any[]>([]); const busy=ref(false); const notice=ref('');
const feedbackBody=ref(''); const feedbackFiles=ref<Attachment[]>([]); const subject=ref(''); const ticketBody=ref(''); const ticketFiles=ref<Attachment[]>([]); const selectedTicket=ref(''); const replyBody=ref(''); const replyFiles=ref<Attachment[]>([]);
const sourceLabels:Record<string,[string,string]>={desktop:['App','Main and windows'],runtime:['Runtime VM','Boot, disk and network'],containers:['Containers','Sulla services'],ai:['AI connections','Claude, Codex and local models']};
const currentTicket=computed(()=>state.value?.tickets.find(t=>t.id===selectedTicket.value)||state.value?.tickets[0]);
const remoteCopy=computed(()=>({idle:['Remote support is off','Request help when setup or Sulla is not working.'],waiting:['Waiting for Sulla support','Your request is saved. You can close this window or restart Sulla.'],approval:['One-time approval needed',`${state.value?.remote.offeredBy||'Sulla support'} is ready to connect. Review the limits before approving.`],connected:['Support is connected','Support can diagnose only inside the Sulla runtime VM.'],ended:['Remote support ended','Access has been removed. Nothing remains connected.']} as any)[state.value?.remote.status||'idle']);
function navigate(v:string){section.value=sections.includes(v as any)?v:'home';if(section.value==='logs')void loadLogs()} function fromHash(){navigate(location.hash.slice(1).split('?')[0])}
async function refresh(){state.value=await ipcRenderer.invoke('support:state');if(!selectedTicket.value&&state.value?.tickets[0])selectedTicket.value=state.value.tickets[0].id} async function loadLogs(){logs.value=await ipcRenderer.invoke('support:logs')}
async function setSource(k:string,v:boolean){state.value=await ipcRenderer.invoke('support:set-source',k,v);await loadLogs()} async function choose(target:any){target.value=[...target.value,...await ipcRenderer.invoke('support:choose-files')].slice(0,10)} function remove(target:any,i:number){target.value.splice(i,1)}
async function submitFeedback(){busy.value=true;try{state.value=await ipcRenderer.invoke('support:add-feedback',{body:feedbackBody.value,attachments:feedbackFiles.value});feedbackBody.value='';feedbackFiles.value=[];notice.value='Feedback saved locally. Cloud delivery follows in the support backend.'}finally{busy.value=false}}
async function createTicket(){busy.value=true;try{state.value=await ipcRenderer.invoke('support:create-ticket',{subject:subject.value,body:ticketBody.value,attachments:ticketFiles.value});selectedTicket.value=state.value!.tickets[0].id;subject.value='';ticketBody.value='';ticketFiles.value=[];notice.value='Ticket created locally.'}finally{busy.value=false}}
async function replyTicket(){if(!currentTicket.value)return;busy.value=true;try{state.value=await ipcRenderer.invoke('support:reply-ticket',{ticketId:currentTicket.value.id,body:replyBody.value,attachments:replyFiles.value});replyBody.value='';replyFiles.value=[]}finally{busy.value=false}} async function remote(a:string){state.value=await ipcRenderer.invoke('support:remote',a)}
const pretty=(v?:string)=>v?new Date(v).toLocaleString():''; const size=(v:number)=>v<1048576?`${Math.max(1,Math.round(v/1024))} KB`:`${(v/1048576).toFixed(1)} MB`; let timer:any; const onNavigate=(_:unknown,v:string)=>navigate(v);
onMounted(async()=>{window.addEventListener('hashchange',fromHash);ipcRenderer.on('support:navigate',onNavigate);fromHash();await refresh();timer=setInterval(()=>{if(section.value==='logs')void loadLogs()},3000)});onBeforeUnmount(()=>{clearInterval(timer);window.removeEventListener('hashchange',fromHash);ipcRenderer.removeListener('support:navigate',onNavigate)});
</script>
<template><div class="shell"><aside><div class="brand"><span>S</span>Sulla <b>Support</b></div><a v-for="s in sections" :key="s" :href="`#${s}`" :class="{on:section===s}">{{{home:'⌂  Support Center',logs:'≡  Logs',feedback:'◇  Feedback',tickets:'▱  Tickets',remote:'↗  Remote support'}[s]}}<em v-if="s==='tickets'&&state?.tickets.length">{{state.tickets.length}}</em><i v-if="s==='remote'&&state?.remote.status==='connected'"></i></a><div class="sidefoot"><div class="device"><b>This Mac</b><label>Sulla Desktop <strong>1.7.5</strong></label><label>Update channel <strong>LTS</strong></label></div><div class="privacy">🔒 Support never sees your Files, passwords or chats.</div></div></aside><main v-if="state"><div v-if="state.remote.status==='connected'" class="connection"><i></i><b>Support is connected</b><span>Inside your Sulla runtime only · reconnects after restarts</span><button @click="remote('end')">End support</button></div><div class="page"><div v-if="notice" class="notice">{{notice}}<button @click="notice=''">×</button></div>
<section v-if="section==='home'"><header><h1>Support Center</h1><p>Get help with Sulla Desktop. Everything here works even if setup didn't finish.</p></header><div v-if="state.logging.lastErrorAt" class="alert warn"><b>Sulla hit an error at {{pretty(state.logging.lastErrorAt)}}.</b> Logging turned on automatically for 24 hours. <a href="#logs">View logs</a></div><div class="tiles"><a href="#logs"><strong>≡</strong><b>Logs</b><span>See what Sulla is doing and turn each source on or off.</span><small>On automatically after an error</small></a><a href="#feedback"><strong>◇</strong><b>Send feedback</b><span>Ideas, bugs or praise. Add screenshots or files.</span><small>Saved locally in this slice</small></a><a href="#tickets"><strong>▱</strong><b>Open a ticket</b><span>Get a written answer and keep replies in a thread.</span><small>{{state.tickets.length}} local ticket(s)</small></a><a href="#remote"><strong>↗</strong><b>Remote support</b><span>Let support diagnose your Sulla runtime with your approval.</span><small>{{state.remote.status}}</small></a></div><div class="card"><h2>Privacy</h2><div><b>Error reports and support state</b><p>Error reporting enables local logging for 24 hours. State lives in userData/support-state.json, never the vault.</p></div></div></section>
<section v-else-if="section==='logs'"><header class="row"><div><h1>Logs</h1><p>Live logs from this Mac and your Sulla runtime.</p></div><button @click="loadLogs">Refresh</button></header><div class="alert"><b>Logging turns on by itself after an error.</b> It stays on for 24 hours. Credential fields are redacted in this viewer.</div><div class="card"><h2>Sources <small v-if="state.logging.autoEnabledUntil">Auto-on until {{pretty(state.logging.autoEnabledUntil)}}</small></h2><div class="sources"><label v-for="(v,k) in sourceLabels" :key="k"><span><b>{{v[0]}}</b><small>{{v[1]}}</small></span><input type="checkbox" :checked="state.logging.sources[k]" @change="setSource(k,($event.target as HTMLInputElement).checked)"></label></div></div><div class="terminal"><template v-if="logs.length"><div v-for="l in logs" :key="l.source+l.name"><b>[{{l.source}} / {{l.name}}]</b>\n{{l.text}}</div></template><span v-else>No log entries found for enabled sources.</span></div></section>
<section v-else-if="section==='feedback'"><header><h1>Send feedback</h1><p>Ideas, bugs or praise. Add screenshots or files.</p></header><div class="form"><label>What would you like us to know?</label><textarea v-model="feedbackBody" maxlength="10000" placeholder="Tell us what happened or what could work better…"></textarea><label>Attachments</label><button class="drop" @click="choose(feedbackFiles)">＋ Choose screenshots or files</button><div class="files"><div v-for="(f,i) in feedbackFiles" :key="f.path"><b>{{f.name}}</b><small>{{size(f.size)}}</small><button @click="remove(feedbackFiles,i)">×</button></div></div><div class="actions"><small>This slice saves feedback locally.</small><button class="primary" :disabled="busy||!feedbackBody.trim()" @click="submitFeedback">Save feedback</button></div></div></section>
<section v-else-if="section==='tickets'"><header class="row"><div><h1>Tickets</h1><p>Create a ticket and keep replies and attachments in one thread.</p></div><button class="primary" @click="selectedTicket='__new'">New ticket</button></header><div class="ticketgrid"><nav class="ticketlist"><button v-for="t in state.tickets" :key="t.id" :class="{on:t.id===currentTicket?.id&&selectedTicket!=='__new'}" @click="selectedTicket=t.id"><b>{{t.subject}}</b><small>{{t.id}} · {{t.replies.length}} replies</small></button><div v-if="!state.tickets.length">No tickets yet.</div></nav><form v-if="selectedTicket==='__new'||!currentTicket" @submit.prevent="createTicket"><h2>Open a ticket</h2><label>Subject</label><input v-model="subject" maxlength="160" placeholder="What do you need help with?"><label>What happened?</label><textarea v-model="ticketBody" maxlength="10000" placeholder="Describe the problem"></textarea><button type="button" @click="choose(ticketFiles)">Attach files</button><div class="files"><div v-for="(f,i) in ticketFiles" :key="f.path"><b>{{f.name}}</b><button type="button" @click="remove(ticketFiles,i)">×</button></div></div><button class="primary" :disabled="busy||!subject.trim()||!ticketBody.trim()">Create ticket</button></form><article v-else class="thread"><header><h2>{{currentTicket.subject}}</h2><small>{{currentTicket.id}} · opened {{pretty(currentTicket.createdAt)}}</small></header><div class="message"><b>You <small>· {{pretty(currentTicket.createdAt)}}</small></b><p>{{currentTicket.body}}</p><small v-if="currentTicket.attachments.length">📎 {{currentTicket.attachments.map(f=>f.name).join(', ')}}</small></div><div v-for="r in currentTicket.replies" :key="r.id" class="message reply"><b>You <small>· {{pretty(r.createdAt)}}</small></b><p>{{r.body}}</p></div><div class="composer"><textarea v-model="replyBody" placeholder="Reply…"></textarea><div><button @click="choose(replyFiles)">Attach</button><button class="primary" :disabled="busy||!replyBody.trim()" @click="replyTicket">Reply</button></div></div></article></div></section>
<section v-else><header><h1>Remote support</h1><p>A Sulla engineer connects to your Sulla runtime and fixes it with you watching.</p></header><div class="remote"><div class="status" :class="state.remote.status"><span v-if="state.remote.status==='waiting'" class="spinner"></span><span v-else>{{state.remote.status==='connected'||state.remote.status==='ended'?'✓':'↗'}}</span></div><h2>{{remoteCopy[0]}}</h2><p>{{remoteCopy[1]}}</p><small>{{pretty(state.remote.endedAt||state.remote.approvedAt||state.remote.offeredAt||state.remote.requestedAt)}}</small><div class="scope"><div><b>✓ Support can</b><ul><li>Read Sulla's logs</li><li>Diagnose inside the runtime VM</li><li>Check and restart Sulla containers</li><li>Retry an AI connection</li></ul></div><div><b>× Support can't</b><ul><li>Run anything on your Mac</li><li>Open your Files or chats</li><li>See passwords or the vault</li><li>Stay connected after you end it</li></ul></div></div><div class="actions center"><button v-if="['idle','ended'].includes(state.remote.status)" class="primary" @click="remote('request')">Request remote support</button><button v-else-if="state.remote.status==='waiting'" class="danger" @click="remote('end')">Cancel request</button><template v-else-if="state.remote.status==='approval'"><button @click="remote('end')">Decline</button><button class="primary" @click="remote('approve')">Allow for up to 48 hours</button></template><button v-else-if="state.remote.status==='connected'" class="danger" @click="remote('end')">End support access</button></div><small>Request, approval and end state persist locally. This slice never executes remote commands.</small></div></section>
</div></main></div></template>
<style scoped>
:global(*){box-sizing:border-box}:global(body){margin:0;font:13px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#1a2332;background:#f4f7fb}.shell{min-height:100vh;display:grid;grid-template-columns:220px 1fr}aside{padding:18px 12px 12px;background:#fff;border-right:1px solid #dde6f0;display:flex;flex-direction:column;gap:3px}.brand{display:flex;align-items:center;gap:5px;font-size:15px;padding:0 9px 20px}.brand>span{display:grid;place-items:center;width:27px;height:27px;border-radius:8px;background:#3a7fa0;color:#fff;margin-right:5px}aside>a{display:flex;align-items:center;gap:7px;padding:7px 10px;border-radius:8px;color:#5b6778;text-decoration:none;font-weight:500;white-space:pre}aside>a.on{background:#e5f0f5;color:#2f6a86;font-weight:600}aside em{margin-left:auto;background:#d9403a;color:#fff;border-radius:9px;padding:0 6px;font-size:10px;font-style:normal}aside i,.connection i{margin-left:auto;width:7px;height:7px;border-radius:50%;background:#1f9d55}.sidefoot{margin-top:auto;display:grid;gap:8px}.device,.privacy{padding:11px;border:1px solid #dde6f0;border-radius:10px;background:#fff;font-size:11.5px;color:#657487}.device{display:grid;gap:4px}.device>b{color:#1a2332}.device label{display:flex;justify-content:space-between;font-weight:400}.device strong{color:#1a2332}.connection{height:40px;background:#1f6b4f;color:#fff;display:flex;align-items:center;gap:10px;padding:0 18px}.connection i{margin:0}.connection button{margin-left:auto;background:#fff;color:#a52b2b;border:0}.page{padding:26px 30px 55px;max-width:1100px}header{margin-bottom:18px}h1{font-size:22px;margin:0}h2{font-size:15px;margin:0}header p{color:#5b6778;margin:4px 0 0}.row{display:flex;justify-content:space-between;align-items:flex-end}.tiles{display:grid;grid-template-columns:1fr 1fr;gap:14px}.tiles a,.card,.form,.remote,form,.thread,.ticketlist{border:1px solid #dde6f0;border-radius:12px;background:#fff;box-shadow:0 8px 24px -18px #445}.tiles a{min-height:145px;padding:16px;display:flex;flex-direction:column;gap:6px;color:inherit;text-decoration:none}.tiles strong{display:grid;place-items:center;width:34px;height:34px;border-radius:9px;background:#e5f0f5;color:#2f6a86;font-size:19px}.tiles span,.tiles small{color:#5b6778}.tiles small{margin-top:auto}.alert,.notice{padding:11px 14px;background:#e7f2f7;border:1px solid #bad7e3;border-radius:9px;margin-bottom:16px}.alert.warn{background:#fff6e6;border-color:#efd7a8}.alert a{float:right}.notice button{float:right;border:0}.card{margin-top:16px}.card h2{padding:13px 16px;border-bottom:1px solid #dde6f0}.card>div{padding:14px 16px}.card p{margin:4px 0;color:#657487}.card h2 small{float:right;font-weight:400}.sources{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.sources label{display:flex;justify-content:space-between;gap:10px;border:1px solid #dde6f0;border-radius:9px;padding:10px}.sources span{display:grid}.sources input{width:auto;accent-color:#3a7fa0}.terminal{margin-top:14px;padding:14px;height:330px;overflow:auto;white-space:pre-wrap;background:#0b111c;color:#c9d4e3;border-radius:10px;font:11.5px/1.6 ui-monospace,monospace}.terminal b{color:#70b5d3}.form,.remote,form{padding:20px;display:grid;gap:9px;max-width:780px}label{font-weight:600}textarea,input{width:100%;border:1px solid #c8d5e4;border-radius:9px;padding:10px 11px;font:inherit;background:#fff}textarea{min-height:130px;resize:vertical}button{border:1px solid #c0ccd8;background:#fff;padding:7px 11px;border-radius:8px;cursor:pointer;font:inherit}.primary{background:#3a7fa0!important;border-color:#3a7fa0!important;color:#fff}.danger{color:#b02c2c;border-color:#efc1c1;background:#fff5f5}.drop{border:1.5px dashed #b6c6d5;padding:16px}.files{display:grid;gap:6px}.files>div{display:flex;align-items:center;gap:9px;padding:8px;border:1px solid #dde6f0;border-radius:8px}.files button{margin-left:auto;border:0}.actions{display:flex;align-items:center;justify-content:flex-end;gap:12px}.actions.center{justify-content:center}small{color:#748293}.ticketgrid{display:grid;grid-template-columns:280px 1fr;gap:16px;align-items:start}.ticketlist{padding:8px;display:grid;gap:4px}.ticketlist button{border:0;text-align:left;display:grid;gap:3px}.ticketlist button.on{background:#e5f0f5;color:#2f6a86}.thread{overflow:hidden}.thread>header{padding:14px 16px;border-bottom:1px solid #dde6f0;margin:0}.message{margin:14px 16px;padding:12px 14px;border:1px solid #dde6f0;border-radius:11px}.message.reply{background:#eaf3f7}.composer{margin:14px 16px;border:1px solid #c8d5e4;border-radius:10px;overflow:hidden}.composer textarea{border:0;min-height:70px}.composer>div{display:flex;justify-content:space-between;padding:8px;border-top:1px solid #dde6f0}.remote{text-align:center}.status{margin:auto;width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:#e5f0f5;color:#2f6a86;font-size:22px}.status.connected,.status.ended{background:#e8f7ee;color:#1f9d55}.scope{display:grid;grid-template-columns:1fr 1fr;gap:12px;text-align:left}.scope>div{padding:13px;border:1px solid #dde6f0;border-radius:10px}.scope ul{padding-left:18px;color:#5b6778;line-height:1.7}.spinner{width:25px;height:25px;border:3px solid #cce0e8;border-top-color:#3a7fa0;border-radius:50%;animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:900px){.sources{grid-template-columns:1fr 1fr}.ticketgrid{grid-template-columns:1fr}.shell{grid-template-columns:190px 1fr}}
</style>
